"""Export briefs and the chart data they cite as static JSON for the web app.

The public site serves these files directly, so visitors never trigger a model call.

    # From a real eval run (briefs generated by Claude)
    python -m idt_copilot.export.static_bundle --briefs-dir evals/runs/<run>/briefs \
        --eval-results evals/runs/<run>/results.json

    # Sample bundle built from the answer keys, for UI development without an API key
    python -m idt_copilot.export.static_bundle --sample

Writes web/public/data/index.json and web/public/data/p/<participant id>.json.
"""
from __future__ import annotations

import argparse
import json
from datetime import datetime, timezone
from pathlib import Path

from idt_copilot.agent.schema import Brief, BriefItem, Verdict
from idt_copilot.chart.repository import ChartRepository
from idt_copilot.models import AnswerKey

SEVERITIES = ("high", "medium", "low")


def sample_brief(key: AnswerKey, summary: dict) -> Brief:
    """A stand-in brief made from the answer key, clearly marked as not generated by Claude."""
    items = [BriefItem(category=t.category, severity=t.severity.value, statement=t.summary,
                       citations=t.supporting_note_ids or ["record:immunizations"], verdict=Verdict.supported,
                       verifier_note="Sample item built from the answer key.")
             for t in sorted(key.must_surface, key=lambda t: SEVERITIES.index(t.severity.value))]
    headline = items[0].statement if items else "No changes needing team discussion."
    return Brief(
        participant_id=key.participant_id, participant_name=f"{summary['first_name']} {summary['last_name']}",
        review_date=str(key.review_date), window_start=str(key.window_start), headline=headline, items=items,
        questions_for_team=["Does the care plan need to change before the next review?"],
        run={"sample": True, "models": {}, "tool_calls": [], "llm_calls": 0, "cost_usd": 0.0, "seconds": 0.0},
    )


def participant_bundle(repo: ChartRepository, brief: Brief) -> dict:
    pid = brief.participant_id
    summary = repo.get_participant_summary(pid)
    notes = {n["id"]: n for n in repo.get_notes(pid, limit=200)}
    cited = {c for item in brief.items + brief.removed_claims for c in item.citations if not c.startswith("record:")}
    for note_id in cited - set(notes):
        try:
            notes[note_id] = repo.get_note(note_id)
        except LookupError:
            pass
    return {
        "participant": summary,
        "brief": brief.model_dump(mode="json"),
        "notes": sorted(notes.values(), key=lambda n: (n["note_date"], n["id"])),
        "records": {
            "record:vitals": repo.get_vitals(pid),
            "record:encounters": repo.get_encounters(pid),
            "record:medications": repo.get_medication_changes(pid),
            "record:immunizations": repo.get_immunizations(pid),
        },
    }


def index_entry(bundle: dict) -> dict:
    p, b = bundle["participant"], bundle["brief"]
    counts = {s: sum(i["severity"] == s for i in b["items"]) for s in SEVERITIES}
    return {
        "id": p["id"], "name": f"{p['first_name']} {p['last_name']}", "age": p["age"], "sex": p["sex"],
        "city": p["city"], "headline": b["headline"], "counts": counts,
        "flags": [i["category"] for i in b["items"] if i["severity"] == "high"][:3],
    }


def main(argv: list[str] | None = None) -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--briefs-dir", type=Path)
    ap.add_argument("--eval-results", type=Path)
    ap.add_argument("--golden-dir", type=Path, default=Path("data/golden"))
    ap.add_argument("--out-dir", type=Path, default=Path("web/public/data"))
    ap.add_argument("--sample", action="store_true", help="build briefs from the answer keys (no Claude)")
    args = ap.parse_args(argv)
    if not args.sample and not args.briefs_dir:
        ap.error("give --briefs-dir, or --sample")

    repo = ChartRepository(use_embeddings=False)
    keys = {k.participant_id: k for k in (AnswerKey.model_validate_json(p.read_text())
                                          for p in sorted(args.golden_dir.glob("*.json")))}
    if args.sample:
        briefs = [sample_brief(k, repo.get_participant_summary(pid)) for pid, k in keys.items()]
    else:
        briefs = [Brief.model_validate_json(p.read_text()) for p in sorted(args.briefs_dir.glob("*.json"))]

    (args.out_dir / "p").mkdir(parents=True, exist_ok=True)
    for old in (args.out_dir / "p").glob("*.json"):
        old.unlink()
    entries = []
    for brief in briefs:
        bundle = participant_bundle(repo, brief)
        (args.out_dir / "p" / f"{brief.participant_id}.json").write_text(json.dumps(bundle))
        entries.append(index_entry(bundle))
    entries.sort(key=lambda e: (-e["counts"]["high"], -e["counts"]["medium"], e["name"]))

    evaluation = None
    if args.eval_results and args.eval_results.exists():
        evaluation = json.loads(args.eval_results.read_text())["summary"]
    any_brief = briefs[0] if briefs else None
    index = {
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "source": "sample" if args.sample else "claude",
        "review_date": any_brief.review_date if any_brief else None,
        "window_start": any_brief.window_start if any_brief else None,
        "models": any_brief.run.get("models", {}) if any_brief else {},
        "evaluation": evaluation,
        "participants": entries,
    }
    (args.out_dir / "index.json").write_text(json.dumps(index, indent=1))
    print(f"Exported {len(entries)} participants to {args.out_dir} ({index['source']} briefs)")


if __name__ == "__main__":
    main()
